import type { IConnector } from '@servicenow/sdk-api'
import { logger } from '../../logger'

/**
 * Status codes returned by GET /api/sn_cicd/progress/{id}. Shared by every operation that
 * kicks off async work on the instance (test runs, app repo install/publish, app install).
 */
export const CicdProgressStatus = {
    PENDING: '0',
    RUNNING: '1',
    SUCCESSFUL: '2',
    ERROR: '3',
    CANCELED: '4',
} as const

const DEFAULT_POLL_INTERVAL_MS = 1000
const LOG_EVERY_N_ATTEMPTS = 10

/** sn_cicd-style async operations return a progress tracker as `result.links.progress.id`. */
export function progressIdFromLinks(result: Record<string, unknown>): string | undefined {
    const links = result?.['links'] as Record<string, unknown> | undefined
    const progress = links?.['progress'] as Record<string, unknown> | undefined
    const id = progress?.['id']
    return typeof id === 'string' ? id : undefined
}

export interface PollProgressOptions {
    intervalMs?: number
    timeoutMs?: number
    onTick?: (progress: ProgressSnapshot, attempt: number) => void
}

export interface ProgressSnapshot {
    status: string
    percentComplete: number
    statusMessage: string
    /**
     * Free-form operation detail, e.g. `"operation=app_install, app=<sys_id>, version=1.2.3,
     * baseVersion=null, ..."` for app_repo install/publish. Format isn't documented/guaranteed
     * consistent across operations — treat as best-effort extra context, not a stable schema.
     */
    statusDetail: string
    /**
     * Raw `links` beyond `links.progress` — e.g. `links.results` for ATF, `links.source` for a
     * scan. Which key exists is operation-specific; `postProcess` reads whatever it needs.
     */
    links: Record<string, { id?: string; url?: string }> | undefined
}

export interface ProgressOutcome extends ProgressSnapshot {
    successful: boolean
}

const TERMINAL_STATUSES: readonly string[] = [
    CicdProgressStatus.SUCCESSFUL,
    CicdProgressStatus.ERROR,
    CicdProgressStatus.CANCELED,
]

/**
 * Polls sn_cicd progress for `progressId` until it reaches a terminal state (successful, error, or
 * canceled), or until `timeoutMs` elapses. Used by every CicdOperation with `poll: true`.
 */
export async function pollProgress(
    connector: IConnector,
    progressId: string,
    options: PollProgressOptions = {}
): Promise<ProgressOutcome> {
    const intervalMs = options.intervalMs ?? DEFAULT_POLL_INTERVAL_MS
    const startedAt = Date.now()
    let attempt = 0

    while (true) {
        const result = await fetchProgress(connector, progressId)
        const snapshot: ProgressSnapshot = {
            status: result.status,
            percentComplete: result.percent_complete,
            statusMessage: result.status_message,
            statusDetail: result.status_detail,
            links: result.links as Record<string, { id?: string; url?: string }> | undefined,
        }

        if (TERMINAL_STATUSES.includes(snapshot.status)) {
            return { ...snapshot, successful: snapshot.status === CicdProgressStatus.SUCCESSFUL }
        }

        if (options.timeoutMs !== undefined && Date.now() - startedAt > options.timeoutMs) {
            throw new Error(
                `Timed out after ${options.timeoutMs}ms waiting on progress '${progressId}'` +
                    (snapshot.statusMessage ? ` (last status: ${snapshot.statusMessage})` : '')
            )
        }

        await new Promise((resolve) => setTimeout(resolve, intervalMs))
        attempt += 1

        if (attempt % LOG_EVERY_N_ATTEMPTS === 0) {
            options.onTick?.(snapshot, attempt)
        }
    }
}

/**
 * Fetches `GET /api/sn_cicd/progress/{progressId}` directly (rather than via `IConnector.getProgress()`,
 * which narrows the response down to `{status, percent_complete, status_message}`) so the full raw body
 * — e.g. `rollback_version`, `status_detail`, `status_label`, `links` — is available to debug-log. Pass
 * `--debug` to see it.
 */
async function fetchProgress(
    connector: IConnector,
    progressId: string
): Promise<{
    status: string
    percent_complete: number
    status_message: string
    status_detail: string
    links?: Record<string, { id?: string; url?: string }>
}> {
    const response = await connector.fetch(`api/sn_cicd/progress/${progressId}`, { method: 'GET' })
    if (!response.ok) {
        throw new Error(`Failed to fetch progress status: ${response.statusText}`)
    }
    const body = await response.json().catch(() => undefined)
    logger.debug(`Progress response for '${progressId}':`, JSON.stringify(body?.result ?? body))
    if (!body?.result) {
        throw new Error(`Progress response for '${progressId}' was missing a result body`)
    }
    return body.result
}

/**
 * Single-shot GET for a result record a `CicdOperation.postProcess` hook wants to fetch once
 * polling has reached a terminal state (e.g. an ATF test/suite result via `links.results.id`).
 * Reuses the same sn_cicd error-shape handling as the initial dispatch fetch in command-builder.ts.
 */
export async function fetchResultBody(connector: IConnector, path: string): Promise<Record<string, unknown>> {
    const response = await connector.fetch(path, { method: 'GET' })
    const body = await response.json().catch(() => undefined)
    if (!response.ok) {
        const message = extractErrorMessage(body) ?? response.statusText
        throw new Error(`Failed to fetch result from '${path}': ${message}`)
    }
    return body ?? {}
}

/**
 * sn_cicd error responses vary in shape:
 *  - Table API lookups used by `resolve` use the generic `{error: {message}}` shape.
 *  - sn_cicd's operations (e.g. `tests/run_test` rejecting a bad test id) return
 *    `{result: {error: "<string>"}}` instead.
 *  - Some failures report only in `result.status_message` and leave `result.error` as an empty
 *    string.
 * Function extracts error message in all three cases.
 */
export function extractErrorMessage(responseBody: unknown): string | undefined {
    const body = responseBody as Record<string, unknown> | undefined
    const genericError = body?.['error'] as Record<string, unknown> | undefined
    const result = body?.['result'] as Record<string, unknown> | undefined
    return (
        nonEmptyString(genericError?.['message']) ??
        nonEmptyString(result?.['error']) ??
        nonEmptyString(result?.['status_message'])
    )
}

function nonEmptyString(value: unknown): string | undefined {
    return typeof value === 'string' && value.trim() !== '' ? value : undefined
}
